  BSP_GPIO_Set(30, 1, 1);
  usleep(10000);
  HAL_PIN_Set(PAD_PA40, I2C1_SCL, PIN_PULLUP, 1);
  HAL_PIN_Set(PAD_PA39, I2C1_SDA, PIN_PULLUP, 1);
  usleep(10000);
}

