  g_vg.imu.fd = -1;
  vg_fall_init(&g_vg.fall_detector);

  ret = vg_imu_open_guarded(&g_vg.imu,
                            CONFIG_CONTEST2026_148_VELAGUARD_IMU_DEVPATH);
  if (ret < 0)
