  g_vg.imu_ready = true;
  g_vg.imu_last_error = 0;
  printf("VelaGuard IMU UI: addr=0x%02x whoami=0x%02x\n",
         g_vg.imu.addr, g_vg.imu.whoami);
  vg_update_imu_labels();
