static void *vg_imu_worker(void *arg)
{
  struct vg_imu_sample_s sample;
  int ret;

  UNUSED(arg);

  for (; ; )
    {
      ret = vg_imu_read_guarded(&g_vg.imu, &sample);
      pthread_mutex_lock(&g_vg.imu_lock);
      if (ret < 0)
        {
          g_vg.imu_worker_error = true;
          g_vg.imu_worker_errno = ret;
        }
      else
        {
          g_vg.imu_sample = sample;
          g_vg.imu_sample_valid = true;
        }

      pthread_mutex_unlock(&g_vg.imu_lock);
      usleep(VG_IMU_WORKER_PERIOD_MS * 1000);
    }

  return NULL;
}

