  76	static uint32_t vg_imu_isqrt64(uint64_t value)
  77	{
  78	  uint64_t bit = (uint64_t)1 << 62;
  79	  uint64_t result = 0;
  80	
  81	  while (bit > value)
  82	    {
  83	      bit >>= 2;
  84	    }
  85	
  86	  while (bit != 0)
  87	    {
  88	      if (value >= result + bit)
  89	        {
  90	          value -= result + bit;
  91	          result = (result >> 1) + bit;
  92	        }
  93	      else
  94	        {
  95	          result >>= 1;
  96	        }
  97	
  98	      bit >>= 2;
  99	    }
 100	
 101	  return (uint32_t)result;
 102	}
