  lv_obj_set_style_text_align(label, align, LV_PART_MAIN);
  lv_obj_set_style_text_color(label, lv_color_hex(color), LV_PART_MAIN);

  return label;
}

static lv_obj_t *vg_action_button(lv_obj_t *parent, const char *text,
