static int board_touch_initialize_with_retry(struct i2c_master_s *i2c)
{
  int ret = -ENODEV;
  int i;

  for (i = 0; i < TOUCH_INIT_RETRY_COUNT; i++)
    {
      usleep(TOUCH_INIT_RETRY_DELAY_US);

      ret = ft6146_touch_initialize(i2c,
                                    GET_PIN_2(hwp_gpio1,
                                              CONFIG_TOUCH_IRQ_PIN));
      if (ret >= 0 || ret == -EEXIST)
