static bool process_pending_cmd(struct bt_dev *hdev, k_timeout_t timeout);
int bt_hci_cmd_send_sync(struct bt_dev *hdev, uint16_t opcode, struct net_buf *buf,
			 struct net_buf **rsp)
{
	struct k_sem sync_sem;
	uint8_t status;
	int err;

	if (!buf) {
		buf = bt_hci_cmd_create(opcode, 0);
		if (!buf) {
			return -ENOBUFS;
		}
	} else {
		/* `cmd(buf)` depends on this  */
		if (net_buf_pool_get(buf->pool_id) != &hci_cmd_pool) {
			__ASSERT_NO_MSG(false);
			return -EINVAL;
		}
	}

	LOG_DBG("buf %p opcode 0x%04x %s len %u", buf, opcode, bt_hci_opcode_to_str(opcode), buf->len);

	/* This local sem is just for suspending the current thread until the
	 * command is processed by the LL. It is given (and we are awaken) by
	 * the cmd_complete/status handlers.
	 */
	k_sem_init(&sync_sem, 0, 1);
	cmd(buf)->sync = &sync_sem;

	k_fifo_put(&hdev->cmd_tx_queue, net_buf_ref(buf));
	syslog(LOG_INFO,
	       "zblue hci sync queued: dev=%u opcode=%04x current=%p syswq=%p\n",
	       hdev->dev_id, opcode, k_current_get(), &k_sys_work_q.thread);
	bt_tx_irq_raise(hdev);

	/* TODO: disallow sending sync commands from syswq altogether */

	/* Since the commands are now processed in the syswq, we cannot suspend
	 * and wait. We have to send the command from the current context.
	 */
	if (k_current_get() == &k_sys_work_q.thread) {
		/* drain the command queue until we get to send the command of interest. */
		struct net_buf *cmd = NULL;

		do {
			cmd = k_fifo_peek_head(&hdev->cmd_tx_queue);
			LOG_DBG("process cmd %p want %p", cmd, buf);

			/* Wait for a response from the Bluetooth Controller.
			 * The Controller may fail to respond if:
			 *  - It was never programmed or connected.
			 *  - There was a fatal error.
			 *
			 * See the `BT_HCI_OP_` macros in hci_types.h or
			 * Core_v5.4, Vol 4, Part E, Section 5.4.1 and Section 7
			 * to map the opcode to the HCI command documentation.
			 * Example: 0x0c03 represents HCI_Reset command.
			 */
			__maybe_unused bool success = process_pending_cmd(hdev, HCI_CMD_TIMEOUT);

			BT_ASSERT_MSG(success, "command opcode 0x%04x %s timeout", opcode, bt_hci_opcode_to_str(opcode));
		} while (buf != cmd);
	}

	/* Now that we have sent the command, suspend until the LL replies */
	err = k_sem_take(&sync_sem, HCI_CMD_TIMEOUT);
	syslog(LOG_INFO,
	       "zblue hci sync wait done: dev=%u opcode=%04x err=%d status=%02x\n",
	       hdev->dev_id, opcode, err, cmd(buf)->status);
	BT_ASSERT_MSG(err == 0,
		      "Controller unresponsive, command opcode 0x%04x %s timeout with err %d",
		      opcode, bt_hci_opcode_to_str(opcode), err);

	status = cmd(buf)->status;
	if (status) {
		LOG_WRN("opcode 0x%04x %s status 0x%02x %s", opcode, bt_hci_opcode_to_str(opcode),
			status, bt_hci_err_to_str(status));
		net_buf_unref(buf);

		return;
	}

	rp = (void *)rsp->data;
	memcpy(ir, rp->ir, 16);

	net_buf_unref(rsp);
#endif /* defined(CONFIG_BT_HCI_VS) */
}
#endif /* defined(CONFIG_BT_PRIVACY) */

uint8_t bt_id_read_public_addr(struct bt_dev *hdev, bt_addr_le_t *addr)
{
	struct bt_hci_rp_read_bd_addr *rp;
	struct net_buf *rsp;
	int err;

	CHECKIF(addr == NULL) {
		LOG_WRN("Invalid input parameters");
		return 0U;
	}

	/* Read Bluetooth Address */
	err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_READ_BD_ADDR, NULL, &rsp);
	if (err) {
		LOG_WRN("Failed to read public address");
		return 0U;
	}

	rp = (void *)rsp->data;

	if (bt_addr_eq(&rp->bdaddr, BT_ADDR_ANY) ||
	    bt_addr_eq(&rp->bdaddr, BT_ADDR_NONE)) {
		LOG_DBG("Controller has no public address");
		net_buf_unref(rsp);
		return 0U;
	}

	bt_addr_copy(&addr->a, &rp->bdaddr);
	addr->type = BT_ADDR_LE_PUBLIC;

	net_buf_unref(rsp);
	return 1U;
}

